<?php
namespace Tests\Feature;use App\Models\DriverEarning;use App\Models\Payment;use App\Models\Trip;use App\Models\User;use App\Services\WompiRefundService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Tests\TestCase;
class WompiRefundTest extends TestCase{use RefreshDatabase;
 protected function setUp():void{parent::setUp();config(['payments.wompi.private_key'=>'prv_test_secret','payments.wompi.api_url'=>'https://sandbox.wompi.test/v1']);}
 private function data():array{$p=User::factory()->create(['role'=>'pasajero']);$d=User::factory()->create(['role'=>'conductor']);$a=User::factory()->create(['role'=>'admin']);$t=Trip::create(['passenger_id'=>$p->id,'driver_id'=>$d->id,'vehicle_type'=>'carro','department'=>'Putumayo','municipality'=>'Mocoa','origin'=>'A','destination'=>'B','origin_lat'=>1,'origin_lng'=>-76,'destination_lat'=>1.1,'destination_lng'=>-76.1,'status'=>'completed','estimated_cost'=>10000,'final_cost'=>10000]);$pay=Payment::create(['trip_id'=>$t->id,'user_id'=>$p->id,'amount'=>10000,'currency'=>'COP','amount_in_cents'=>1000000,'status'=>'completed','provider'=>'wompi','provider_reference'=>'TRIP-R','provider_transaction_id'=>'tx-approved']);$earning=DriverEarning::create(['trip_id'=>$t->id,'driver_id'=>$d->id,'gross_amount'=>10000,'commission_rate'=>12,'platform_fee'=>1200,'net_amount'=>8800,'status'=>'available']);return [$pay,$earning,$a];}
 public function test_approved_partial_refund_adjusts_unpaid_driver_balance():void{[$payment,$earning,$admin]=$this->data();Http::fake(['*'=>Http::response(['data'=>['status'=>'APPROVED','v2_refund_id'=>'refund-1']],201)]);$refund=app(WompiRefundService::class)->request($payment,250000,'Solicitud pasajero',$admin->id);$this->assertSame('approved',$refund->status);$this->assertSame('7500.00',$earning->fresh()->gross_amount);$this->assertSame('6600.00',$earning->fresh()->net_amount);Http::assertSent(fn($r)=>$r->hasHeader('Authorization','Bearer prv_test_secret')&&$r['transaction_id']==='tx-approved');}
 public function test_reserved_refunds_cannot_exceed_original_payment():void{[$payment,,$admin]=$this->data();Http::fake(['*'=>Http::response(['data'=>['status'=>'APPROVED','v2_refund_id'=>'refund-1']],201)]);$service=app(WompiRefundService::class);$service->request($payment,800000,'Primer reembolso',$admin->id);$this->expectException(\DomainException::class);$service->request($payment,300000,'Segundo reembolso',$admin->id);}
}